"""Convert lm_eval --log_samples output to IRT-compatible format.

lm_eval saves per-sample JSONL files under:
  <output_path>/<model_name>/samples_<task>_<timestamp>.jsonl

This script finds all samples_*.jsonl, extracts per-item correctness,
and writes eval_results.json, correctness_matrix.json, item_responses.json
matching the format expected by downstream IRT analysis.
"""
import argparse
import json
from pathlib import Path


BENCHMARK_MAP = {
    "arc_challenge": "arc_challenge",
}


def normalize_benchmark(task_name):
    """Map lm_eval task name to our benchmark name."""
    if task_name in BENCHMARK_MAP:
        return BENCHMARK_MAP[task_name]
    if task_name.startswith("mmlu_"):
        return "mmlu"
    return task_name


def extract_correct(sample, task_name):
    """Extract correctness from a lm_eval sample dict."""
    if "acc" in sample:
        return bool(sample["acc"])
    if "exact_match" in sample:
        return bool(sample["exact_match"])
    if "filtered_resps" in sample and "target" in sample:
        pred = sample["filtered_resps"][0] if sample["filtered_resps"] else ""
        return str(pred).strip() == str(sample["target"]).strip()
    return False


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--input-dir", required=True, help="lm_eval output root dir")
    parser.add_argument("--output-dir", required=True, help="IRT output dir")
    args = parser.parse_args()

    input_dir = Path(args.input_dir)
    output_dir = Path(args.output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
